const rows=[{"status": 100, "label": "Continue", "retryable": false, "refreshAuth": false}, {"status": 103, "label": "Early Hints", "retryable": false, "refreshAuth": false}, {"status": 200, "label": "OK", "retryable": false, "refreshAuth": false}, {"status": 201, "label": "Created", "retryable": false, "refreshAuth": false}, {"status": 204, "label": "No Content", "retryable": false, "refreshAuth": false}, {"status": 301, "label": "Moved Permanently", "retryable": false, "refreshAuth": false}, {"status": 302, "label": "Found", "retryable": false, "refreshAuth": false}, {"status": 304, "label": "Not Modified", "retryable": false, "refreshAuth": false}, {"status": 400, "label": "Bad Request", "retryable": false, "refreshAuth": false}, {"status": 401, "label": "Unauthorized", "retryable": false, "refreshAuth": true}, {"status": 403, "label": "Forbidden", "retryable": false, "refreshAuth": false}, {"status": 404, "label": "Not Found", "retryable": false, "refreshAuth": false}, {"status": 408, "label": "Request Timeout", "retryable": true, "refreshAuth": false}, {"status": 409, "label": "Conflict", "retryable": false, "refreshAuth": false}, {"status": 422, "label": "Unprocessable Entity", "retryable": false, "refreshAuth": false}, {"status": 425, "label": "Too Early", "retryable": true, "refreshAuth": false}, {"status": 429, "label": "Too Many Requests", "retryable": true, "refreshAuth": false}, {"status": 500, "label": "Internal Server Error", "retryable": true, "refreshAuth": false}, {"status": 502, "label": "Bad Gateway", "retryable": true, "refreshAuth": false}, {"status": 503, "label": "Service Unavailable", "retryable": true, "refreshAuth": false}, {"status": 504, "label": "Gateway Timeout", "retryable": true, "refreshAuth": false}];
export function classifyStatus(status){
 if(!Number.isInteger(status)||status<100||status>599)return {category:'unknown',label:'Unknown status',retryable:false,refreshAuth:false};
 const row=rows.find(item=>item.status===status),category=status<200?'informational':status<300?'success':status<400?'redirect':status<500?'client_error':'server_error';
 return {category,label:row?row.label:'Unknown status',retryable:row?row.retryable:false,refreshAuth:row?row.refreshAuth:false};
}

